const items = $input.all();
const results = [];
for (const item of items) {
  const g = item.json;
  const reward = Number(g.reward_brl || 15.00);
  const minutes = Number(g.est_minutes || 10);
  const hourlyRate = (reward / minutes) * 60;
  let score = 60;
  let priority = 'NORMAL';
  if (hourlyRate >= 60) { score = 95; priority = 'CRITICAL_BUG'; }
  else if (hourlyRate >= 40) { score = 80; priority = 'HIGH'; }
  results.push({
    json: {
      category: 'microtask_gig',
      title: `Microtarefa (${g.platform || 'Appen/Remotasks'}): ${g.title || 'Rotulação / Validação'}`,
      description: `Pagamento: R$ ${reward.toFixed(2)} por ${minutes}m (Taxa Horária R$ ${hourlyRate.toFixed(2)}/h). Execução rápida online.`,
      opportunity_price: reward,
      original_price: reward,
      net_profit_estimate: reward,
      source_name: g.platform || 'Microtask Hub',
      source_url: g.url || 'https://exemplo.com',
      evaluation_score: score,
      priority
    }
  });
}
return results;
